//
// The hill of hillclimb ([HILLCLIMB] 1), from its parameters alone:
// what voxel is at a place, so that a section is generated by asking this
// for each of its voxels, and the same parameters always give the same
// hill. No engine types: the module and the self test (-DHILL_TEST) both
// include it.
//
// **A world unit is one voxel, 125 mm** (U = 8 to the metre): voxelworld
// has no scale, so every length in metres is multiplied by U on its way
// in, the car's and the camera's as well as the hill's.
//
// Along +Z: a flat pad at the bottom, the slope, a flat pad at the top.
// Across X: a bank of rock a metre wide and a metre high, the track 8 m
// wide, the other bank; banks across both ends too, so a car that keeps
// going stops at the top's and does not drop off it, and a stone rolling
// down stops at the bottom's. Under the surface a shell of sand with pebbles
// (stones 2 to 3 voxels across) 1.5 m deep, then a fill nobody sees.
// The slope's angle is the middle's; its ends ease in and out over 2 m,
// so the car does not meet a kink at either pad.
#pragma once
#include <cmath>
#include <cstdint>

namespace hill {

static const int U = 8; // voxels to the metre
static const float PI = 3.14159265f;

enum Voxel { AIR, SAND, STONE, FILL, BANK };

struct Params
{
	uint32_t seed = 1;
	float steep_deg = 22; // the middle's slope
	float length_m = 50;  // the slope's run along Z
	// simplified: sand with pebbles is the only terrain; rocky, muddy and
	// vegetated are later ([HILLCLIMB] 5)
};

struct Hill
{
	Params p;
	// In voxels
	static const int PAD = 6 * U;      // each flat pad, longer than the car
	static const int EASE = 2 * U;     // the slope's ends, eased
	static const int BANK_W = 1 * U;   // each bank's width
	static const int BANK_H = 1 * U;   // and height over the track
	static const int TRACK_W = 8 * U;
	static const int SHELL = 12;       // sand's depth, 1.5 m
	static const int BASE = 2 * U;     // the bottom pad's surface over y 0
	static const int BUMP = 1;         // the surface's undulation, voxels
	int run = 0;                       // the slope's run
	float k = 0;                       // the middle's rise per voxel
	float rise = 0;

	Hill(const Params &params): p(params)
	{
		run = (int)std::lround(p.length_m * U);
		k = std::tan(p.steep_deg * PI / 180);
		// Each eased end rises half of what a straight one would
		rise = k * (run - EASE);
	}

	int size_x() const { return 2 * BANK_W + TRACK_W; }
	int size_z() const { return 2 * PAD + run; }
	int size_y() const { return BASE + (int)std::ceil(rise) + BANK_H + BUMP + 8; }
	// Where the slope starts and where the top pad does, along Z
	int slope_z0() const { return PAD; }
	int top_z0() const { return PAD + run; }
	// The surface's height over the bottom pad at z, unbumped: the slope's
	// rise integrated, its rate easing from 0 to k over EASE at each end
	float profile(float z) const
	{
		float u = z - PAD;
		if(u <= 0)
			return 0;
		if(u >= run)
			return rise;
		const float e = EASE;
		if(u < e)
			return k * u * u / (2 * e);
		if(u > run - e){
			float v = run - u;
			return rise - k * v * v / (2 * e);
		}
		return k * e / 2 + k * (u - e);
	}

	static uint32_t hash(uint32_t a, uint32_t b, uint32_t c, uint32_t d)
	{
		uint32_t h = a * 0x9e3779b1u ^ b * 0x85ebca77u ^ c * 0xc2b2ae3du ^
				d * 0x27d4eb2fu;
		h ^= h >> 15; h *= 0x2c1b3c6du; h ^= h >> 12; h *= 0x297a2d39u;
		return h ^ (h >> 15);
	}
	float unit(uint32_t a, uint32_t b, uint32_t c, uint32_t d) const
	{
		return (hash(a, b, c, d ^ p.seed) & 0xffffff) / (float)0x1000000;
	}
	// Value noise, 0..1, cells of `cell` voxels
	float noise(float x, float z, int cell, uint32_t salt) const
	{
		float fx = x / cell, fz = z / cell;
		int ix = (int)std::floor(fx), iz = (int)std::floor(fz);
		float tx = fx - ix, tz = fz - iz;
		tx = tx * tx * (3 - 2 * tx);
		tz = tz * tz * (3 - 2 * tz);
		auto at = [&](int a, int b){ return unit(a, b, salt, 0); };
		float a = at(ix, iz) + (at(ix + 1, iz) - at(ix, iz)) * tx;
		float b = at(ix, iz + 1) + (at(ix + 1, iz + 1) - at(ix, iz + 1)) * tx;
		return a + (b - a) * tz;
	}
	// The track's surface: the top voxel's y at (x, z). The pads are flat;
	// the slope undulates by up to BUMP, faded in from its ends
	int surface(int x, int z) const
	{
		float h = BASE + profile(z + 0.5f);
		float u = (z + 0.5f - PAD) / (float)EASE;
		float w = u <= 0 ? 0 : u >= 1 ? 1 : u;
		float v = (top_z0() - z - 0.5f) / (float)EASE;
		w *= v <= 0 ? 0 : v >= 1 ? 1 : v;
		h += w * BUMP * (2 * noise(x, z, 3 * U, 1) - 1);
		return (int)std::floor(h);
	}
	// A pebble: in a 4-voxel cell, a stone of radius 1..1.6 voxels about a
	// point in it, one cell in five. pebble_of() says which: its centre in
	// voxel coordinates (a voxel's centre is its integer position) and its
	// radius, for the ground to loosen it whole ([HILLCLIMB] 4).
	bool pebble_of(int x, int y, int z, float &ox, float &oy, float &oz,
			float &radius) const
	{
		const int C = 4;
		int cx = (int)std::floor(x / (float)C), cy = (int)std::floor(y / (float)C),
				cz = (int)std::floor(z / (float)C);
		for(int dz = -1; dz <= 1; dz++)
		for(int dy = -1; dy <= 1; dy++)
		for(int dx = -1; dx <= 1; dx++){
			int a = cx + dx, b = cy + dy, c = cz + dz;
			if(unit(a, b, c, 7) >= 0.2f)
				continue;
			float px = (a + unit(a, b, c, 11)) * C, py = (b + unit(a, b, c, 13)) * C,
					pz = (c + unit(a, b, c, 17)) * C;
			float r = 1.0f + 0.6f * unit(a, b, c, 19);
			float qx = x + 0.5f - px, qy = y + 0.5f - py, qz = z + 0.5f - pz;
			if(qx * qx + qy * qy + qz * qz <= r * r){
				ox = px - 0.5f;
				oy = py - 0.5f;
				oz = pz - 0.5f;
				radius = r;
				return true;
			}
		}
		return false;
	}
	bool pebble(int x, int y, int z) const
	{
		float a, b, c, r;
		return pebble_of(x, y, z, a, b, c, r);
	}

	Voxel at(int x, int y, int z) const
	{
		if(x < 0 || x >= size_x() || z < 0 || z >= size_z() || y < 0)
			return AIR;
		const int s = surface(x, z);
		const bool bank = x < BANK_W || x >= BANK_W + TRACK_W ||
				z < BANK_W || z >= size_z() - BANK_W;
		if(bank)
			return y <= s + BANK_H ? BANK : AIR;
		if(y > s)
			return AIR;
		if(y <= s - SHELL)
			return FILL;
		return pebble(x, y, z) ? STONE : SAND;
	}
};

} // namespace hill

#ifdef HILL_TEST
#include <cassert>
#include <cstdio>
int main()
{
	using namespace hill;
	Params p;
	Hill a(p), b(p);
	// The same seed, the same hill; another seed, another
	Params q = p; q.seed = 2;
	Hill c(q);
	int same = 0, differ = 0;
	for(int z = 0; z < a.size_z(); z += 3)
	for(int y = 0; y < a.size_y(); y += 2)
	for(int x = 0; x < a.size_x(); x += 3){
		same += a.at(x, y, z) == b.at(x, y, z);
		differ += a.at(x, y, z) != c.at(x, y, z);
		assert(a.at(x, y, z) == b.at(x, y, z));
	}
	assert(differ > 0);
	// The slope within a few degrees of the asked one along its middle,
	// measured over each 4 m
	for(int z = a.slope_z0() + Hill::EASE; z + 4 * U <=
			a.top_z0() - Hill::EASE; z += 4 * U){
		float m = 0;
		for(int x = Hill::BANK_W; x < Hill::BANK_W + Hill::TRACK_W; x++)
			m += a.surface(x, z + 4 * U) - a.surface(x, z);
		m /= Hill::TRACK_W * 4.0f * U;
		float deg = std::atan(m) * 180 / PI;
		assert(std::fabs(deg - p.steep_deg) < 3);
	}
	// The pads flat and as long as the car (2.8 m wheelbase, 0.8 m tyres)
	for(int x = Hill::BANK_W; x < Hill::BANK_W + Hill::TRACK_W; x++){
		for(int z = 0; z < Hill::PAD; z++)
			assert(a.surface(x, z) == Hill::BASE);
		int top = a.surface(x, a.top_z0());
		for(int z = a.top_z0(); z < a.size_z(); z++)
			assert(a.surface(x, z) == top);
	}
	assert(Hill::PAD >= (int)(3.6f * U));
	// 8 m of track between the banks, sand on top with stones in it
	assert(Hill::TRACK_W == 8 * U);
	int sand = 0, stone = 0;
	for(int z = Hill::BANK_W; z < a.size_z() - Hill::BANK_W; z++)
	for(int x = Hill::BANK_W; x < Hill::BANK_W + Hill::TRACK_W; x++){
		int s = a.surface(x, z);
		assert(a.at(x, s + 1, z) == AIR);
		assert(a.at(x, s, z) != AIR && a.at(x, s, z) != FILL);
		for(int y = s - Hill::SHELL + 1; y <= s; y++){
			sand += a.at(x, y, z) == SAND;
			stone += a.at(x, y, z) == STONE;
		}
		assert(a.at(x, s - Hill::SHELL, z) == FILL);
	}
	assert(stone > sand / 50 && stone < sand / 2);
	assert(a.at(0, a.surface(0, 10) + Hill::BANK_H, 10) == BANK);
	// The top's far end walled, and the top pad still longer than the car
	int end = a.size_z() - 1;
	assert(a.at(40, a.surface(40, end) + Hill::BANK_H, end) == BANK);
	assert(Hill::PAD - Hill::BANK_W >= (int)(3.6f * U));
	assert(a.at(40, a.surface(40, 0) + Hill::BANK_H, 0) == BANK);
	// The car's start (main.cpp: the pad's middle) clear of the bottom's
	// bank: the rear tyre's back 1.4 + 0.4 m behind it
	assert(Hill::PAD / 2 - (int)std::ceil(1.8f * U) >= Hill::BANK_W);
	printf("hill.h: self test passed; %dx%dx%d voxels, rise %.1f m, "
			"%.1f%% stones in the shell\n", a.size_x(), a.size_y(), a.size_z(),
			a.rise / U, 100.0f * stone / (sand + stone));
	return 0;
}
#endif
